import { useEffect, useState } from 'react';

function PiStatsTable() {
  const [stats, setStats] = useState(null);

  useEffect(() => {
    fetch("http://localhost:8000/api/pi_stats")
      .then(response => response.json())
      .then(data => setStats(data))
      .catch(error => console.error("Error fetching Pi stats:", error));
  }, []);

  if (!stats) return <p>Loading...</p>;

  return (
    <div>
      <h2>Raspberry Pi Stats</h2>
      <table>
        <thead>
          <tr>
            <th>CPU1 Usage (%)</th>
            <th>CPU2 Usage (%)</th>
            <th>CPU3 Usage (%)</th>
            <th>CPU4 Usage (%)</th>
            <th>CPU Temperature (°C)</th>
            <th>CPU Frequency (GHz)</th>
            <th>Total Memory (GB)</th>
            <th>Memory Usage (%)</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td>{stats.CPU1_usage} </td>
            <td>{stats.CPU2_usage}</td>
            <td>{stats.CPU3_usage}</td>
            <td>{stats.CPU4_usage}</td>
            <td>{stats.CPU_temperature}</td>
            <td>{stats.CPU_frequency}</td>
            <td>{stats.Total_memory}</td>
            <td>{stats.Memory_usage}</td>
          </tr>
        </tbody>
      </table>
    </div>
  );
}

export default PiStatsTable;
